local function sameFlat(a,b)
  if #a ~= #b then return false end
  for i=1,#a do if a[i] ~= b[i] then return false end end
  return true
end

local function sameRows(a,b)
  if #a ~= #b then return false end
  for i=1,#a do
    if not sameFlat(a[i],b[i]) then return false end
  end
  return true
end

local function signature(graph)
  if type(graph) ~= "table" or graph.invalid or type(graph.order) ~= "table"
      or type(graph.nodes) ~= "table" or type(graph.roots) ~= "table"
      or type(graph.chains) ~= "table" then return nil end
  local nodes,roots,edges,chains,semantics,seen = {},{},{},{},{},{}
  for _,name in ipairs(graph.order) do
    if type(name) ~= "string" or seen[name] then return nil end
    local node=graph.nodes[name]
    if type(node) ~= "table" or type(node.parents) ~= "table" then return nil end
    seen[name]=true
    nodes[#nodes+1]=name
    if type(node.family) ~= "string" or type(node.orPrereqs) ~= "table" then return nil end
    local alternatives={}
    for _,p in ipairs(node.orPrereqs) do
      if type(p) ~= "string" then return nil end
      alternatives[#alternatives+1]=p
    end
    table.sort(alternatives)
    semantics[#semantics+1]={name,node.family,node.requiredPrereq or "",
                            table.concat(alternatives,"|")}
    for _,parent in ipairs(node.parents) do
      if type(parent) ~= "string" then return nil end
      edges[#edges+1]={parent,name}
    end
  end
  local count=0
  for name in pairs(graph.nodes) do
    count=count+1
    if not seen[name] then return nil end
  end
  if count ~= #nodes then return nil end
  for _,name in ipairs(graph.roots) do
    if type(name) ~= "string" then return nil end
    roots[#roots+1]=name
  end
  for _,chain in ipairs(graph.chains) do
    if type(chain) ~= "table" then return nil end
    for _,name in ipairs(chain) do if type(name) ~= "string" then return nil end end
    chains[#chains+1]=table.concat(chain,"|")
  end
  table.sort(nodes)
  table.sort(semantics,function(a,b) return a[1]<b[1] end)
  table.sort(roots)
  table.sort(chains)
  table.sort(edges,function(a,b)
    if a[1] ~= b[1] then return a[1] < b[1] end
    return a[2] < b[2]
  end)
  return {nodes=nodes,roots=roots,edges=edges,chains=chains,semantics=semantics}
end

local function exactMatch(actual)
  for _,profile in ipairs(profiles) do
    local expected=profile.signature
    if sameFlat(actual.nodes,expected.nodes)
        and sameFlat(actual.roots,expected.roots)
        and sameFlat(actual.chains,expected.chains)
        and sameRows(actual.edges,expected.edges)
        and sameRows(actual.semantics,expected.semantics) then return profile end
  end
  return nil
end

local function retainedRows(rows,keep)
  local result={}
  for _,row in ipairs(rows) do
    if keep[row[1]] then result[#result+1]=row end
  end
  return result
end

local function retainedFlat(values,keep)
  local result={}
  for _,value in ipairs(values) do
    if keep[value] then result[#result+1]=value end
  end
  return result
end

local function retainedEdges(edges,keep)
  local result={}
  for _,edge in ipairs(edges) do
    if keep[edge[1]] and keep[edge[2]] then result[#result+1]=edge end
  end
  return result
end

local function retainedChains(chains,keep)
  local result={}
  for _,chain in ipairs(chains) do
    local members={}
    for name in string.gmatch(chain,"[^|]+") do
      if keep[name] then members[#members+1]=name end
    end
    if #members>=2 then result[#result+1]=table.concat(members,"|") end
  end
  table.sort(result)
  return result
end

local function inducedSubset(actual,expected,keep)
  -- Reuse a reviewed arrangement only after removing whole components. An
  -- omitted promotion joined to a survivor would change that survivor's
  -- routed neighborhood, even if the remaining edge list were induced.
  for _,edge in ipairs(expected.edges) do
    if keep[edge[1]] ~= keep[edge[2]] then return false end
  end
  if not sameFlat(actual.roots,retainedFlat(expected.roots,keep)) then return false end
  if not sameFlat(actual.chains,retainedChains(expected.chains,keep)) then return false end
  if not sameRows(actual.semantics,retainedRows(expected.semantics,keep)) then return false end
  return sameRows(actual.edges,retainedEdges(expected.edges,keep))
end

local function match(graph)
  local actual=signature(graph)
  if not actual then return nil end
  local exact=exactMatch(actual)
  if exact then return exact end
  local keep={}
  for _,name in ipairs(actual.nodes) do keep[name]=true end
  local best,bestDistance,tied
  for _,profile in ipairs(profiles) do
    local expected=profile.signature
    local distance=#expected.nodes-#actual.nodes
    if distance>0 and (not bestDistance or distance<=bestDistance) then
      local present=0
      for _,name in ipairs(expected.nodes) do
        if keep[name] then present=present+1 end
      end
      if present==#actual.nodes and inducedSubset(actual,expected,keep) then
        if not bestDistance or distance<bestDistance then
          best,bestDistance,tied=profile,distance,false
        else
          tied=true
        end
      end
    end
  end
  if tied then return nil end
  return best,keep
end

-- Metadata lets the UI select compact cards before measuring its viewport.
function PromotionReviewedGraphMatch(graph)
  local profile=match(graph)
  if not profile then return nil end
  return {name=profile.name,status=profile.status,buttonW=160,buttonH=46}
end

local function copy(value)
  if type(value) ~= "table" then return value end
  local result={}
  for key,item in pairs(value) do result[key]=copy(item) end
  return result
end

local function projectLayout(layout,keep)
  local projected={buttons={},routes={},sourceRoutes={},source=copy(layout.source)}
  for _,button in ipairs(layout.buttons) do
    if keep[button.type] then projected.buttons[#projected.buttons+1]=copy(button) end
  end
  for _,route in ipairs(layout.routes) do
    if keep[route.parent] and keep[route.child] then
      projected.routes[#projected.routes+1]=copy(route)
    end
  end
  for _,route in ipairs(layout.sourceRoutes) do
    if keep[route.child] then projected.sourceRoutes[#projected.sourceRoutes+1]=copy(route) end
  end
  return projected
end

-- Return an unvalidated candidate. PromotionCheckLayout remains the sole
-- acceptance gate; it reconstructs crossing gaps and checks every edge.
function PromotionReviewedLayout(graph,geom)
  local profile,keep=match(graph)
  if not profile or type(geom) ~= "table" then return nil end
  if geom.buttonW ~= 160 or geom.buttonH ~= 46 or geom.pipeHalfWidth ~= 4 then return nil end
  local viewW,viewH=geom.viewportW,geom.viewportH
  if type(viewW) ~= "number" or type(viewH) ~= "number" or viewW <= 0 or viewH <= 0 then return nil end
  local scale=math.min(1,viewW/profile.extentW,viewH/profile.extentH)
  if scale < math.sqrt(2/3) then return nil end
  local layout=keep and projectLayout(profile.layout,keep) or copy(profile.layout)
  layout.width=viewW/scale
  layout.height=viewH/scale
  layout.scale=scale
  layout.method="reviewed"
  local checkedGeometry={}
  for key,value in pairs(geom) do checkedGeometry[key]=value end
  checkedGeometry.readabilityCrossingBudget=profile.budget
  return layout,checkedGeometry,profile.name
end
